import{z as s,x as A,o as n,c as d,q as l,j as r,D as e,d as E,s as o,S as B,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"线性注意力的内核化","description":"","frontmatter":{"title":"线性注意力的内核化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ak-linear-attention-kernel.md","filePath":"llm/ak-linear-attention-kernel.md","lastUpdated":1791063341000}'),m={name:"llm/ak-linear-attention-kernel.md"};function p(h,a,_,D,C,f){const i=A("Mermaid");return n(),d("div",null,[a[2]||(a[2]=l('<h1 id="线性注意力的内核化" tabindex="-1">线性注意力的内核化 <a class="header-anchor" href="#线性注意力的内核化" aria-label="Permalink to &quot;线性注意力的内核化&quot;">​</a></h1><div class="epigraph"><p>线性注意力把 $n\\times n$ 换成一个 $d\\times d$ 状态；这个状态住在哪一层存储，决定它是省内存的数学还是省时间的内核。</p><footer>—— 据 Katharopoulos et al., 2020；门控线性注意力（2023）实现整理</footer></div><p><a href="/llm/ak-sparse-kernel-strategy">上一课</a>让图跳块省算。本课是变体单元的最后一课，动得更深：把 \\(n\\times n\\) 本身换掉。<a href="/llm/linear-attention">Linear Attention</a> 在数学侧给过核特征、并行形式与状态递推，<a href="/llm/gated-linear-attention">门控线性注意力 GLA</a> 加了衰减门；本课只问内核化：并行、递推、分块三种形式各落在哪一层存储，哪一种才真的快。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>并行形式先算 \\(\\phi(Q)\\phi(K)^\\top\\) 再乘 \\(V\\)：中间要么是 \\(n\\times d&#39;\\) 的特征张量、要么是 \\(d&#39;\\times d&#39;\\) 逐位置的秩一项，总之把要省掉的与 \\(n\\) 同阶的东西换了个名字存进 HBM，省内存与省时间都没兑现。递推形式 \\(S_t=S_{t-1}+\\phi(k_t)^\\top v_t\\) 逐 token 更新，状态虽是常数大小，但每步一次核调用、串行 \\(n\\) 次，GPU 利用率崩掉。两头都对、两头都不可用——同一份数学在内核上变成了两难。缺口是一个能同时喂饱带宽与并发的形式。</p><p><span class="marginnote">直觉类比：递推状态 \\(S\\) 像一本固定大小的笔记——每读一个新 token 就把要点记进去，旧记录被融合覆盖。所以不管文章多长，本子始终只有 \\(d&#39;\\times d&#39;\\) 那么大；代价是没法像 KV 缓存那样逐字回看原文，重点一旦被压缩就回不来了。</span></p><h3 id="三种形式-一张表" tabindex="-1">三种形式，一张表 <a class="header-anchor" href="#三种形式-一张表" aria-label="Permalink to &quot;三种形式，一张表&quot;">​</a></h3><p>并行形式吃显存、递推形式吃并发，分块形式各取一半：块内用并行形式算局部二次项，块间用递推传状态。它对 FlashAttention 的骨架似是而非——外层都扫块——但传的东西不同：FA 传的是每行三个统计量，这里传的是整张 \\(d&#39;\\times d&#39;\\) 状态矩阵。</p>',8)),(n(),r(B,null,{default:e(()=>[o(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%B9%B6%E8%A1%8C%E5%BD%A2%E5%BC%8F%3A%20%E4%B8%80%E6%AC%A1%E7%AE%97%E5%85%A8%E9%83%A8%22%5D%20--%3E%20P1%5B%22%E4%B8%AD%E9%97%B4%E5%BC%A0%E9%87%8F%E4%B8%8E%20n%20%E5%90%8C%E9%98%B6%3A%20%E5%90%83%E6%98%BE%E5%AD%98%22%5D%0A%20%20R%5B%22%E9%80%92%E6%8E%A8%E5%BD%A2%E5%BC%8F%3A%20%E9%80%90%20token%20%E4%B8%B2%E8%A1%8C%22%5D%20--%3E%20R1%5B%22n%20%E6%AC%A1%E5%86%85%E6%A0%B8%E5%90%AF%E5%8A%A8%3A%20%E5%90%83%E5%B9%B6%E5%8F%91%22%5D%0A%20%20C%5B%22%E5%88%86%E5%9D%97%E5%BD%A2%E5%BC%8F%22%5D%20--%3E%20C1%5B%22%E5%9D%97%E5%86%85%E5%B9%B6%E8%A1%8C%E7%AE%97%E5%B1%80%E9%83%A8%E9%A1%B9%22%5D%0A%20%20C%20--%3E%20C2%5B%22%E5%9D%97%E9%97%B4%E9%80%92%E6%8E%A8%E4%BC%A0%20d'%C3%97d'%20%E7%8A%B6%E6%80%81%22%5D%0A%20%20C1%20--%3E%20OUT%5B%22%E5%B8%A6%E5%AE%BD%E4%B8%8E%E5%B9%B6%E5%8F%91%E4%B8%A4%E5%A4%B4%E9%83%BD%E5%96%82%E9%A5%B1%22%5D%0A%20%20C2%20--%3E%20OUT%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[t("span",{class:"marginnote"},"术语翻译：分块形式就是「块内并行、块间串行」。同一块内部的计算互不依赖，可以大规模铺开并行算；只有块与块之间要按顺序交接状态。和 FlashAttention 外表像，但 FA 块间只传每行的三个统计量，这里传的是整张状态矩阵。")],-1)),a[4]||(a[4]=t("h2",{id:"方法",tabindex:"-1"},[E("方法 "),t("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),a[5]||(a[5]=t("p",null,"分块内核的写法。块 \\(j\\) 内：先算局部项 \\((\\phi(Q_j)\\phi(K_j)^\\top\\odot M_j)V_j\\)（块内掩码），再算跨块项 \\(\\phi(Q_j)S_{j-1}\\)——历史状态与当前查询的一次矩阵乘；输出两项相加。块间：\\(S_j=S_{j-1}\\cdot D_j+\\phi(K_j)^\\top V_j\\)，\\(D_j\\) 是门控衰减（无门时是单位阵）。训练时状态链有前缀和结构，块内输出全并行、状态链按结合律合并，SM 排得满；解码时 \\(S\\) 常驻显存，每步读 \\(\\phi(q),v\\)、写 \\(\\Delta S\\)，带宽 \\(O(d^2)\\)、与 \\(n\\) 无关——「常数状态」的内核含义就是这条带宽。",-1)),(n(),r(B,null,{default:e(()=>[o(i,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%9D%97%20j%EF%BC%9A%E8%BD%BD%E5%85%A5%20%CF%86(Q_j)%E3%80%81K_j%E3%80%81V_j%22%5D%20--%3E%20B%5B%22%E5%9D%97%E5%86%85%E5%B9%B6%E8%A1%8C%EF%BC%9A%E6%8E%A9%E7%A0%81%E4%BA%8C%E6%AC%A1%E9%A1%B9%22%5D%0A%20%20S0%5B%22%E4%B8%8A%E4%B8%80%E5%9D%97%E7%8A%B6%E6%80%81%20S_%7Bj-1%7D%22%5D%20--%3E%20C%5B%22%E8%B7%A8%E5%9D%97%E9%A1%B9%EF%BC%9A%CF%86(Q_j)%20%C2%B7%20S_%7Bj-1%7D%22%5D%0A%20%20B%20--%3E%20OUT%5B%22%E8%BE%93%E5%87%BA%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20C%20--%3E%20OUT%0A%20%20OUT%20--%3E%20U%5B%22%E7%8A%B6%E6%80%81%E6%9B%B4%E6%96%B0%EF%BC%9AS_j%20%3D%20S_%7Bj-1%7D%C2%B7D_j%20%2B%20%CF%86(K_j)%5ET%20V_j%22%5D%0A%20%20U%20--%3E%20NEXT%5B%22%E4%BC%A0%E7%BB%99%E4%B8%8B%E4%B8%80%E5%9D%97%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>把两难拆开看，就懂分块为什么成立：二次项只在块内出现，块大小 \\(B\\) 固定，中间张量是 \\(B\\times B\\) 而不是 \\(n\\times n\\)；状态是块间的唯一通道，\\(d&#39;=128\\)、fp16 时每头 \\(32\\,\\mathrm{KiB}\\)，驻在 smem 或寄存器里都放得下——第一单元的预算表原样适用，只是住户从 Q、K、V 块换成了状态与特征块。错法回到两头：天真并行形式把 \\(\\phi(Q)\\phi(K)^\\top\\) 物化成 \\(n\\times d&#39;\\) 与 \\(d&#39;\\times n\\) 相乘，显存与流量回到与 \\(n\\) 同阶；递推写成逐 token 内核，\\(n\\) 次启动的固定开销与每次都冷的缓存，让纸面上的 \\(O(n)\\) 在墙钟上输给二次的 FlashAttention。</p><p><span class="marginnote">\\(d&#39;=128\\)、fp16：每头状态 \\(32\\,\\mathrm{KiB}\\)；\\(n=32\\mathrm{k}\\) 时 MHA 每头的 K+V 约 \\(16\\,\\mathrm{MiB}\\)——同一头缓存容量差约五百倍，解码带宽从随 \\(n\\) 线性变成常数。这就是「线性」在系统层的真实含义。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>核特征不逼近 softmax：精确拷贝弱、尖峰打不出来，这是<a href="/llm/linear-attention">线性注意力</a>数学课的边界，内核不负责救质量。门控衰减 \\(D_j\\) 若逐头不同，状态更新多一组标量通道，扫描的结合律仍在，只是合并公式多乘一项。与 MHA 混层、混合架构是模型设计的题目；训练侧的反向（状态链的伴随）本课不展开。质量之争到此为止：本课程的立场是——任何变体先要能被写快，才轮到比较质量。</p><p><span class="marginnote">常见误区：初学者容易以为「线性复杂度一定比二次快」。若把递推写成逐 token 的小内核，几百次启动开销加冷缓存，纸面的 \\(O(n)\\) 在实际墙钟上会输给写得好的二次 FlashAttention。复杂度是渐近账，墙钟才是结账单。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>并行形式吃显存、递推形式吃并发；分块形式块内并行、块间传状态，两头都活。</li><li>与 FA 的骨架同构但通道不同：传的是 \\(d&#39;\\times d&#39;\\) 状态矩阵，不是标量统计量。</li><li>解码收益的内核含义：状态常驻，每步带宽 \\(O(d^2)\\) 与上下文长度无关。</li><li>物化特征外积或逐 token 启动内核，是两头都赔回去的典型错法。</li><li>预算表换个住户继续用：状态与特征块同样要在 smem 与寄存器额度里安家。</li><li>出处：Katharopoulos et al., <em>Transformers are RNNs</em>, ICML 2020；据 GLA 与 Lightning Attention 实现整理。</li></ul>',8))])}const j=s(m,[["render",p]]);export{u as __pageData,j as default};
